// Jackal Refuge (Play as Nabooru mod): the scorching atmosphere of the area.
//
// The scene itself is generated by tools/build_jackal_refuge.py. It turns the game's sky and sun off; this file draws
// their replacements around the camera every frame (called from the scene's draw config in z_scene_table.c):
//  - a cloudless sky with a white-hot sun (SkyDL), behind everything
//  - the game's own lens flare and glare, when looking towards that sun
// and tints the picture slightly warm.

#include "soh/Enhancements/game-interactor/GameInteractor.h"
#include "soh/ShipInit.hpp"
#include <cmath>
#include "soh/frame_interpolation.h" // gives OPEN_DISPS' interpolation calls C linkage in this C++ file

extern "C" {
#include "z64.h"
#include "macros.h"
#include "functions.h"
#include "variables.h"
extern PlayState* gPlayState;
void JackalRefuge_Draw(PlayState* play);
}

#define JACKAL_REFUGE_DL(name) ((Gfx*)"__OTR__scenes/shared/jackal_refuge_scene/jackal_refuge_" name)

// Where the sun stands (as SUN_AZIMUTH / SUN_ELEVATION in build_jackal_refuge.py): degrees clockwise from north
// (-z), and above the horizon.
static const float SUN_AZIMUTH = 250.0f;
static const float SUN_ELEVATION = 40.0f;
// The warm tint over the picture.
static const Color_RGBA8 HEAT_TINT = { 255, 150, 40, 16 };

void JackalRefuge_Draw(PlayState* play) {
    const Vec3f& eye = play->view.eye;

    OPEN_DISPS(play->state.gfxCtx);

    // sky and sun: around the camera, drawn before the scenery without touching the depth buffer
    Matrix_Translate(eye.x, eye.y, eye.z, MTXMODE_NEW);
    gSPMatrix(POLY_OPA_DISP++, MATRIX_NEWMTX(play->state.gfxCtx), G_MTX_NOPUSH | G_MTX_LOAD | G_MTX_MODELVIEW);
    gSPDisplayList(POLY_OPA_DISP++, JACKAL_REFUGE_DL("SkyDL"));

    CLOSE_DISPS(play->state.gfxCtx);

    // the game's lens flare, at our sun (the environment is set up again, flare off, on every scene load)
    float azimuth = SUN_AZIMUTH * (float)M_PI / 180.0f;
    float elevation = SUN_ELEVATION * (float)M_PI / 180.0f;
    gCustomLensFlareOn = true;
    gCustomLensFlarePos.x = eye.x + 3000.0f * sinf(azimuth) * cosf(elevation);
    gCustomLensFlarePos.y = eye.y + 3000.0f * sinf(elevation);
    gCustomLensFlarePos.z = eye.z - 3000.0f * cosf(azimuth) * cosf(elevation);
    gLensFlareScale = 330;
    gLensFlareColorIntensity = 60.0f;
    gLensFlareScreenFillAlpha = 70;
}

static void RegisterJackalRefuge() {
    // after the whole world is drawn, under the HUD
    COND_HOOK(OnPlayDrawEnd, true, []() {
        if (gPlayState != NULL && gPlayState->sceneNum == SCENE_JACKAL_REFUGE) {
            Environment_FillScreen(gPlayState->state.gfxCtx, HEAT_TINT.r, HEAT_TINT.g, HEAT_TINT.b, HEAT_TINT.a,
                                   FILL_SCREEN_XLU);
        }
    });
}

static RegisterShipInitFunc initFunc(RegisterJackalRefuge, {});
